/// <summary>
/// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
/// To initialise TAMRebateTrans from METRebateScanSupplierTable (Vendor)
/// </summary>
using System.ComponentModel.Composition;

[ExportAttribute(identifierStr(Dynamics.AX.Application.TAMRebateJournalTrans))]
[ExportMetadata(enumStr(ModuleInventCustVend), enumLiteralStr(ModuleInventCustVend, Vend))]
[ExportMetadata(enumStr(TAMRebateSourceType), enumLiteralStr(TAMRebateSourceType, METExternalSalesData))]
public final class METTAMRebateJournalTransVendExternalData extends METTAMRebateJournalTransExternalData
{    
    VendTable vendTable;

}

Method.Source:
/// <summary>
/// Set journal transaction, simplified from TAMRebateJournalTransPurchOrder
/// </summary>
/// <param name = "_journal"><t>METRebateScanSupplierTable</t></param>
/// <param name = "_transaction"><t>METRebateScanSupplierTable</t></param>
public void setJournalTransaction(Common _journal, Common _transaction)
{     
    super(_journal, _transaction);

    vendTable = VendTable::find(externalSalesData.VendAccount);
    taxGroup = vendTable.TaxGroup;

    //taxModuleType = purchTable.taxModuleType();
    taxModuleType = TaxModuleType::Purch;
}

/// <summary>
/// Init rebate trans from journal
/// </summary>
/// <param name = "_rebateTrans"><t>TAMRebateTrans</t></param>
public void inititalizeRebateTransactionFromJournal(TAMRebateTrans _rebateTrans)
{
    super(_rebateTrans);

    _rebateTrans.DefaultDimension = vendTable.DefaultDimension; //will be initialised from vendor rebate type when journals are created
    _rebateTrans.RebateRefSoldToAccount = vendTable.InvoiceAccount;
}
